using MiniPharmacie.Business.Models;
using MiniPharmacie.Business.Services;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.App.Forms;

public sealed class ProductsForm : PharmacyForm
{
    private readonly StockManagementService service=new(new DatabaseInitializer());
    private readonly long userId;
    private readonly DataGridView grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
    private readonly TextBox search=new(){Width=260,PlaceholderText="Référence ou désignation"};
    public ProductsForm(long authenticatedUserId){userId=authenticatedUserId;Text="Produits";Width=1050;Height=680;MinimumSize=new Size(760,480);StartPosition=FormStartPosition.CenterParent;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=54,Padding=new Padding(10)};var add=new Button{Text="Nouveau produit",AutoSize=true};var edit=new Button{Text="Modifier",AutoSize=true};var archive=new Button{Text="Archiver / supprimer",AutoSize=true};var refresh=new Button{Text="Actualiser",AutoSize=true};bar.Controls.AddRange([search,refresh,add,edit,archive]);Controls.Add(grid);Controls.Add(bar);refresh.Click+=async(_,_)=>await LoadProducts();search.TextChanged+=async(_,_)=>await LoadProducts();add.Click+=async(_,_)=>{if(EditProduct(null) is { } draft){try{await service.SaveProductAsync(draft,userId);await LoadProducts();}catch(Exception ex){MessageBox.Show(ex.Message,"Saisie non enregistrée",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}};edit.Click+=async(_,_)=>{if(grid.CurrentRow?.DataBoundItem is ProductStock row&&EditProduct(row) is{} draft){try{await service.SaveProductAsync(draft,userId,row.ProductId);await LoadProducts();}catch(Exception ex){MessageBox.Show(ex.Message,"Saisie non enregistrée",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}};archive.Click+=async(_,_)=>{if(grid.CurrentRow?.DataBoundItem is ProductStock row&&MessageBox.Show($"Archiver ou supprimer « {row.Name} » ?","Confirmation",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){try{await service.ArchiveOrDeleteProductAsync(row.ProductId,userId);await LoadProducts();}catch(Exception ex){MessageBox.Show(ex.Message,"Opération impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}};Shown+=async(_,_)=>await LoadProducts();}
    private async Task LoadProducts(){try{grid.DataSource=await service.GetProductsAsync(search.Text.Length==0?null:search.Text,active:null);}catch(Exception ex){MessageBox.Show(ex.Message,"Erreur",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    private static ProductDraft? EditProduct(ProductStock? current){using var f=new PharmacyForm{Text=current is null?"Nouveau produit":"Modifier le produit",Width=450,Height=540,FormBorderStyle=FormBorderStyle.FixedDialog,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false};var names=new[]{"Référence","Désignation","Dosage","Forme pharmaceutique","Unité de vente","Prix (centimes)","Seuil minimal","Code-barres (facultatif)","Emplacement (facultatif)"};var boxes=new TextBox[names.Length];for(var i=0;i<names.Length;i++){f.Controls.Add(new Label{Text=names[i],Left=18,Top=18+i*45,Width=170});boxes[i]=new TextBox{Left=195,Top=15+i*45,Width=220};f.Controls.Add(boxes[i]);}if(current is not null){boxes[0].Text=current.Code;boxes[1].Text=current.Name;boxes[4].Text="boîte";boxes[5].Text="0";boxes[6].Text=current.ReorderLevel.ToString();}else{boxes[4].Text="boîte";boxes[5].Text="0";boxes[6].Text="0";}var save=new Button{Text="Enregistrer",Left=285,Top=430,Width=125,DialogResult=DialogResult.OK};f.Controls.Add(save);f.AcceptButton=save;if(f.ShowDialog()!=DialogResult.OK)return null;if(!long.TryParse(boxes[5].Text,out var price)||!int.TryParse(boxes[6].Text,out var threshold))throw new ArgumentException("Le prix et le seuil doivent être des nombres entiers valides.");return new(boxes[0].Text,boxes[1].Text,null,boxes[2].Text,boxes[3].Text,boxes[4].Text,price,threshold,boxes[7].Text.Length==0?null:boxes[7].Text,boxes[8].Text.Length==0?null:boxes[8].Text);}
}
